// What the model reads for a call's outcome: the host's envelope, or the
// session's own words for its tools.
json AgentHost::tool_output_json(const ToolActivity& activity) const
{
    json output{{"state", tool_state_name(activity.state)}};
    if (!activity.result_json.empty())
        output["result"] = parsed_or_object(activity.result_json);
    if (activity.error)
        output["error"] = json{{"code", activity.error->code}, {"message", activity.error->message},
                                {"details", json::parse(activity.error->details_json)}};
    if (m_session_tool_output)
        if (std::optional<json> own = m_session_tool_output(activity))
            output = std::move(*own);
    return output;
}

void AgentHost::continue_after_tool(const ToolActivity& activity)
{
    const auto found = m_tool_continuations.find(activity.action_id);
    if (found == m_tool_continuations.end())
        return;

    PendingToolContinuation continuation = found->second;
    m_tool_continuations.erase(found);

    json       output = tool_output_json(activity);
    AgentToolResult result;
    // A session about something other than the project is never told about
    // the project, in its tool results any more than in its turns.
    if (m_session_profile.include_workspace) {
        const WorkspaceSnapshot current_workspace = m_workspace.snapshot();
        output["actionId"]          = activity.action_id;
        output["workspaceRevision"] = current_workspace.revision;
        // The plan's real validity, which a person's or another client's
        // edit since setup_record pinned it may have put in doubt. The chat's setup title
        // and headline are the agent's own words, so they are not repeated.
        const PlanRecord plan = m_persistence.document().plan();
        output["workspace"] = context_json(current_workspace);
        output["workspace"]["planValidity"]      = plan.validity;
        output["workspace"]["planInvalidatedBy"] = plan.invalidated_by;
        // A call that opened or imported a file brings its load report back
        // in this result, which is where the model first reads it.
        if (brings_load_report(activity))
            if (std::optional<AgentSkillUse> skill = fire_skill(Protocol::SkillTrigger::kFileLoaded,
                                                                continuation.conversation_id, current_workspace))
                result.skills.push_back(std::move(*skill));
        // The model's own setup change needs no reminder: the setup it chose
        // counts as checked, so it is not later read as unchecked.
        if (activity.tool == "printer_setup" && activity.state == ToolState::Succeeded &&
            purpose_recorded(continuation.conversation_id))
            mark_setup_checked(current_workspace);
            break;
        }
    }
    push(messages, "user", std::move(content));
    push_skills(messages, transcript.opening_once);
    for (const TurnStep& step : transcript.steps) {
        // The response's own content, thinking included, exactly as it came.
        push(messages, "assistant", step.assistant_turn);
        json results = json::array();
        for (const TurnStepResult& result : step.results) {
            json block{{"type", "tool_result"}, {"tool_use_id", result.call_id}};
            json parts = json::array({text_block(result.output_json)});
            if (result.image)
                parts.push_back(image_block(result.image->mime_type, result.image->base64));
            block["content"] = std::move(parts);
            if (result.failed)
                block["is_error"] = true;
            results.push_back(std::move(block));
        }
        push(messages, "user", std::move(results));
        // Kept on every later request, where it was first sent: removing it
        // would change the history before the thinking that followed it.
        push_skills(messages, step.once);

        if (!http.headers.count("mcp-name") || !name || *name != params["name"].get<std::string>())
            return error(400, -32020, "Missing, malformed, or mismatched Mcp-Name header.");
        if (params.contains("arguments") && !params["arguments"].is_object())
            return error(400, -32602, "Tool arguments must be an object.", {{"code", "invalid_arguments"}});
    }
    return {Request{id, method, params}, {}};
}

Reply discovery(const Request& request)
{
    return {200, rpc_result(request.id, {{"supportedVersions", json::array({kProtocolVersion})},
                                         {"capabilities", {{"tools", {{"listChanged", false}}}}},
                                         {"ttlMs", 0},
                                         {"cacheScope", "private"},
                                         {"instructions", "For a requested settings change, inspect the live workspace, search or read the relevant settings, then preview a patch. Apply with the "
                                     "sessionId and revision from that preview. After stale_workspace, read and preview again. Project "
                                     "Undo does not reverse preset edits; use preset revert or an inverse patch. A workspace_unavailable "
                                     "error means you should open JusPrin and a project. Closing a response cancels pending work."}})};
}

Reply list_tools(const Request& request, std::size_t page_size)
{
    const auto definitions = Agent::ToolRegistry::instance().exposed(Agent::ToolExposure::Mcp);
    std::size_t offset = 0;
    if (request.params.contains("cursor")) {
        const json& cursor = request.params["cursor"];
        if (!cursor.is_string()) return {400, rpc_error(request.id, -32602, "Invalid catalog cursor.")};
        const std::string text = cursor.get<std::string>();
        constexpr std::string_view prefix = "jusprin-v1:";
        if (text.compare(0, prefix.size(), prefix) != 0)
            return {400, rpc_error(request.id, -32602, "Invalid catalog cursor.")};
        const auto parsed = std::from_chars(text.data() + prefix.size(), text.data() + text.size(), offset);
        if (parsed.ec != std::errc() || parsed.ptr != text.data() + text.size() || offset >= definitions.size())
            return {400, rpc_error(request.id, -32602, "Invalid catalog cursor.")};
    }
    json tools = json::array();
    const std::size_t end = std::min(definitions.size(), offset + std::clamp<std::size_t>(page_size, 1, 25));
    for (; offset < end; ++offset) {
        const Agent::ToolDefinition& tool = definitions[offset];
        const bool read_only = tool.action_class == Agent::ActionClass::ReadOnly;
        // No outputSchema on the wire: no client is known to use it, and it was
        // two thirds of the catalog's bytes. Results are still checked against
        // it internally on every success (see activity_result below).
        tools.push_back({{"name", tool.name}, {"title", tool.title}, {"description", tool.description},
                         {"inputSchema", tool.input_schema},
                         {"annotations", {{"readOnlyHint", read_only}, {"destructiveHint", tool.action_class == Agent::ActionClass::Destructive},
                                           {"idempotentHint", read_only}, {"openWorldHint", false}}}});
    }
    json result{{"tools", std::move(tools)}, {"ttlMs", 0}, {"cacheScope", "private"}};
    if (end < definitions.size()) result["nextCursor"] = "jusprin-v1:" + std::to_string(end);
    return {200, rpc_result(request.id, std::move(result))};
}

json tool_error(const std::string& code, const std::string& message, json details)
{
    return {{"error", {{"code", code}, {"message", message}, {"details", std::move(details)}}}};
}

json tool_result(json content, bool is_error)
{
    return {{"resultType", "complete"}, {"isError", is_error},
            {"content", json::array({{{"type", "text"}, {"text", content.dump()}}})},
            {"structuredContent", std::move(content)}};
}

json activity_result(const Agent::ToolActivity& activity, const Workspace::WorkspaceSnapshot& snapshot)
{
    using Agent::ToolState;
    json result;
    if (activity.state == ToolState::Succeeded) {
        const auto content = json::parse(activity.result_json);
        const auto* definition = Agent::ToolRegistry::instance().find(activity.tool);
        if (!definition || !Agent::ToolRegistry::instance().validate_output(*definition, content))
            throw std::logic_error("Tool result violates its canonical output schema: " + activity.tool);
        result = tool_result(content);
        if (activity.image)
            result["content"].push_back({{"type", "image"}, {"data", activity.image->base64}, {"mimeType", activity.image->mime_type}});
    } else {
        std::string code = "execution_failed", message = "Tool execution failed.";
        if (activity.state == ToolState::Cancelled) { code = "cancelled"; message = "The action was cancelled."; }
        else if (activity.error) { code = activity.error->code; message = activity.error->message; }
        json details = activity.error ? json::parse(activity.error->details_json) : json::object();
        if (code == "stale_revision" || code == "stale_id") {
            std::string expected_session = std::to_string(activity.session);
            if (code == "stale_id") {
                const json arguments = json::parse(activity.arguments_json);
                expected_session = arguments.value("sessionId", expected_session);
            }
            code = "stale_workspace";
            details = {{"expectedSessionId", expected_session}, {"expectedRevision", activity.expected_revision},
                       {"currentSessionId", std::to_string(snapshot.session.value())}, {"currentRevision", snapshot.revision}};
        } else if (code == "unavailable_operation") code = "workspace_unavailable";
        result = tool_result(tool_error(code, message, std::move(details)), true);
    }
    result["_meta"]["io.jusprin/activity"] = {{"actionId", activity.action_id},
                                              {"sessionId", std::to_string(snapshot.session.value())},
                                              {"revision", snapshot.revision}};
    return result;
}

std::string mcp_client_name(const json& params)
{
    const json info = params.value("_meta", json::object()).value("io.modelcontextprotocol/clientInfo", json::object());
    if (!info.is_object()) return {};
    // A title is the name meant for people ("Claude Code"); the name is an
    // identifier ("claude-code"), shown only when there is no title.
    const auto text = [&info](const char* field) {
        std::string value = info.value(field, json()).is_string() ? info[field].get<std::string>() : std::string();
        for (char& c : value)
            if (static_cast<unsigned char>(c) < 0x20 || c == 0x7f) c = ' ';
        return trim(std::move(value));
    };
    std::string name = text("title");
    if (name.empty()) name = text("name");
    if (name.size() > kClientNameLimit) {
        std::size_t end = kClientNameLimit;
        while (end > 0 && (static_cast<unsigned char>(name[end]) & 0xc0) == 0x80) --end; // whole UTF-8 characters only
        name = trim(name.substr(0, end));
    }
    return name;
}

