std::size_t object_count(const WorkspaceSnapshot& snapshot)
{
    std::set<ObjectId> ids;
    for (const WorkspacePlate& plate : snapshot.plates)
        for (const WorkspaceObject& object : plate.objects)
            ids.emplace(object.id);
    return ids.size();
}

